572	int ObPxTransmitOp::send_rows_one_by_one(ObSliceIdxCalc &slice_calc)
573	{
574	  int ret = OB_SUCCESS;
575	  int64_t send_row_time_recorder = 0;
576	  int64_t row_count = 0;
577	  ObObj tablet_id;
578	
579	  ObSliceIdxCalc::SliceIdxArray slice_idx_array;
580	  ObPhysicalPlanCtx *phy_plan_ctx = GET_PHY_PLAN_CTX(ctx_);
581	  if (OB_ISNULL(phy_plan_ctx)) {
582	    ret = OB_ERR_UNEXPECTED;
583	    LOG_WARN("physical plan ctx is null", K(ret));
584	  }
585	  while (OB_SUCC(ret)) {
586	    clear_evaluated_flag();
587	    const ObPxTransmitSpec &spec = static_cast<const ObPxTransmitSpec &>(get_spec());
588	    ret = next_row();
589	    if (OB_FAIL(ret)) {
590	      if (OB_UNLIKELY(OB_ITER_END != ret)) {
591	        LOG_WARN("fail to get next row from child op",
592	                 K(ret), K(child_->get_spec().get_type()));
593	      } else {
594	        // iter end
595	        const ObPxTransmitSpec &spec = static_cast<const ObPxTransmitSpec &>(get_spec());
596	        if (OB_FAIL(try_wait_channel())) {
597	          LOG_WARN("failed to wait channel init", K(ret));
598	        } else if (batch_param_remain_) {
599	          ret = OB_SUCCESS;
600	          ObPxNewRow px_eof_row;
601	          px_eof_row.set_eof_row();
602	          px_eof_row.set_data_type(data_msg_type_);
603	          for (int i = 0; i < task_channels_.count() && OB_SUCC(ret); i++) {
604	            dtl::ObDtlChannel *ch = task_channels_.at(i);
605	            if (OB_FAIL(ch->send(px_eof_row, phy_plan_ctx->get_timeout_timestamp(), &eval_ctx_, false))) {
606	              LOG_WARN("fail send eof row to slice channel", K(px_eof_row), K(ret));
607	            } else if (OB_FAIL(ch->push_buffer_batch_info())) {
608	              LOG_WARN("channel push back batch failed", K(ret));
609	            }
610	          }
611	        } else if (OB_FAIL(send_eof_row())) { // overwrite err code
612	          LOG_WARN("fail send eof rows to channels", K(ret));
613	        }
614	        break;
615	      }
616	    }
617	    row_count++;
618	    metric_.count();
619	    if (OB_FAIL(ret)) {
620	      LOG_WARN("fail to get next row", K(ret));
621	    } else if (OB_FAIL(set_rollup_hybrid_keys(slice_calc))) {
622	      LOG_WARN("failed to set rollup hybrid keys", K(ret));
623	    } else if (OB_FAIL(set_wf_hybrid_slice_id_calc_type(slice_calc))) {
624	      LOG_WARN("failed to set rollup hybrid keys", K(ret));
625	    } else if (OB_FAIL((slice_calc.get_slice_indexes<CALC_TYPE, false>(
626	                       get_spec().output_, eval_ctx_, slice_idx_array)))) {
627	      LOG_WARN("fail get slice idx", K(ret));
628	    } else if (dfc_.all_ch_drained()) {
629	      int tmp_ret = child_->drain_exch();
630	      if (OB_SUCCESS != tmp_ret) {
631	        LOG_WARN("drain exchange data failed", K(tmp_ret));
632	      }
633	      ret = OB_ITER_END;
634	      LOG_DEBUG("all channel has been drained");
635	    } else if (NULL != spec.tablet_id_expr_
636	               && OB_FAIL(slice_calc.get_previous_row_tablet_id(tablet_id))) {
637	      LOG_WARN("failed to get previous row tablet_id", K(ret));
638	    }
639	    FOREACH_CNT_X(slice_idx, slice_idx_array, OB_SUCC(ret)) {
640	      if (OB_FAIL(send_row(*slice_idx, send_row_time_recorder, tablet_id.get_int()))) {
641	        if (OB_ITER_END != ret) {
642	          LOG_WARN("fail emit row to interm result", K(ret), K(slice_idx_array));
643	        }
644	      }
645	    }
646	  }
647	  if (OB_ITER_END == ret) {
648	    ret = OB_SUCCESS;
649	    LOG_TRACE("transmit meet a iter end");
650	  }
651	  LOG_TRACE("Transmit time record", K(row_count), K(ret));
652	  return ret;
653	}
