173	int ObPxTransmitOp::inner_open()
174	{
175	  int ret = OB_SUCCESS;
176	  // 这里是一个特殊处理逻辑，本质上是先inner_open然后open最后面打上tag
177	  // 但是现在transmit有个特殊地方在于inner_open会调用get_next_row，这样导致如果iter_end
178	  // 就会走到drain_exec，这个会判断，如果没有open，会先open
179	  // 所以如果inner_open里面嵌套了get_next_row，则opened_ flag就没有设置，这样在drain逻辑里面就会一直open
180	  // 导致函数栈溢出core掉
