192	    // for fast init sqc we can not access rpc process time here
193	    SET_METRIC_VAL(ObMetricId::SQC_RPC_PROCESS_COST,
194	                   sqc_metrics.sqc_rpc_process_cost_);
195	    if (sqc_metrics.sqc_rpc_after_cost_ > 0) {
196	      SET_METRIC_VAL(ObMetricId::SQC_RPC_AFTER_PROCESS_COST,
