203	  const ObIArray<ObExpr *> &trans_exprs = spec.real_trans_exprs_.count() > 0 ? spec.real_trans_exprs_ : spec.output_;
204	  if (OB_ISNULL(child_)) {
205	    ret = OB_ERR_UNEXPECTED;
