568	int ObDtlBasicChannel::process1(
569	    ObIDtlChannelProc *proc,
570	    int64_t timeout,
571	    bool &last_row_in_buffer)
572	{
573	  int ret = OB_SUCCESS;
574	  last_row_in_buffer = false;
575	  if (timeout < 0) {
576	    ret = OB_INVALID_ARGUMENT;
577	    LOG_ERROR("timeout is invalid", K(ret));
578	  } else {
579	    if (!use_interm_result()) {
580	      do {
581	        if (nullptr == process_buffer_ && OB_FAIL(get_processed_buffer(timeout))) {
582	          if (OB_DTL_WAIT_EAGAIN == ret) {
583	          } else {
584	            LOG_WARN("failed to get buffer", K(ret));
585	          }
586	        } else if (nullptr != process_buffer_) {
587	          auto &buffer = process_buffer_;
588	          bool transferred = false;
589	          ret = proc->process(*buffer, transferred);
590	          LOG_DEBUG("process buffer", K(ret), KP(buffer), K(transferred));
591	          if (buffer->is_data_msg()) {
592	            metric_.set_last_out_ts(::oceanbase::common::ObTimeUtility::current_time());
593	          }
594	          if (OB_ITER_END == ret || transferred) {
595	            inc_processed_buffer_cnt();
596	            if (buffer->is_eof()) {
597	              if (buffer->is_data_msg()) {
598	                metric_.mark_eof();
599	              }
600	              if (!is_eof()) {
601	                if (NULL != channel_loop_) {
602	                  channel_loop_->inc_eof_cnt();
603	                }
604	                set_eof();
605	                ret = OB_SUCCESS;
606	                if (nullptr != msg_watcher_) {
607	                  msg_watcher_->remove_data_list(this);
608	                }
609	              } else {
610	                ret = OB_DTL_WAIT_EAGAIN;
611	              }
612	            }
613	            LOG_TRACE("process one piece", KP(id_), K_(peer), K(ret),
614	                      K(get_processed_buffer_cnt()), K(get_recv_buffer_cnt()),
615	                      K(buffer->is_data_msg()), K(buffer->is_eof()),
616	                      K(transferred));
617	            int tmp_ret = ret;
618	            if (OB_SUCCESS != (tmp_ret = unblock_on_decrease_size(buffer->size()))) {
619	              ret = tmp_ret;
620	              LOG_WARN("failed to decrease buffer size for dfc",
621	                       KP(id_), K_(peer), K(ret), K(get_processed_buffer_cnt()),
622	                       K(get_recv_buffer_cnt()));
623	            }
624	            if (transferred) {
625	              // only increase the statist
626	              free_buffer_count();
627	            } else {
628	              free_buf(buffer);
629	            }
630	            buffer = nullptr;
631	            // 测试发现每次一个channel读数据，性能更好，将之前由读一个buffer改为读一个channel所有buffer
632	            // last_row_in_buffer = true;
633	          }
634	        }
635	      } while (OB_ITER_END == ret);
636	    } else {
637	      ObDTLIntermResultInfo *result_info = NULL;
638	      ObDTLIntermResultKey key;
639	      key.channel_id_ = id_;
640	      key.batch_id_ = batch_id_;
641	      MTL_SWITCH(tenant_id_) {
642	        if (channel_is_eof_) {
643	          ret = OB_DTL_WAIT_EAGAIN;
644	        } else if (OB_FAIL(MTL(ObDTLIntermResultManager*)->atomic_get_interm_result_info(
645	              key, result_info_guard_))) {
646	          if (is_px_channel()) {
647	            ret = OB_DTL_WAIT_EAGAIN;
648	          // This will result in ret = OB_SUCCESS and result_info being null.
649	          } else if (ignore_error()) {
650	            ret = OB_SUCCESS;
651	          } else {
652	            LOG_WARN("fail to get row store", K(ret));
653	          }
654	          LOG_TRACE("fail to get row store", K(ret), K(key.batch_id_), K(key.channel_id_));
655	        } else if (FALSE_IT(result_info = result_info_guard_.result_info_)) {
656	        } else if (OB_SUCCESS != result_info->ret_) {
657	          ret = result_info->ret_;
658	          LOG_WARN("the interm result info meet a error", K(ret));
659	        } else if (!result_info->is_store_valid()) {
660	          ret = OB_ERR_UNEXPECTED;
661	          LOG_WARN("there is no row store in internal result", K(ret));
662	        } else if (OB_FAIL(DTL_IR_STORE_DO(*result_info, finish_add_row, true))) {
663	          LOG_WARN("failed to finish add row", K(ret));
664	        } else if (!result_info->is_rich_format()) {
665	          if (OB_FAIL(result_info->datum_store_->begin(datum_iter_))) {
666	            LOG_WARN("begin iterator failed", K(ret));
667	          }
668	        } else {
669	          if (OB_FAIL(result_info->get_row_store()->begin(row_iter_))) {
670	            LOG_WARN("failed to begin chunk row store.", K(ret));
671	          }
672	        }
673	      }
674	      if (OB_SUCC(ret) && !channel_is_eof()) {
675	        ObDtlLinkedBuffer mock_buffer;
676	        mock_buffer.set_data_msg(true);
677	        ObDtlMsgType type = ObDtlMsgType::PX_DATUM_ROW;
678	        if (OB_ISNULL(result_info) || !result_info->is_rich_format()) {
679	          mock_buffer.set_buf(reinterpret_cast<char *>(&datum_iter_), sizeof(datum_iter_));
